// ---------------------------------------------------------------------------
// tb_functional.v -- INDEPENDENT functional testbench for edge_llm_matmul_accel
//
// This TB contains NO golden arithmetic.  It only:
//   (1) reads pre-packed operand words + pre-computed EXPECTED output bytes
//       generated by the from-scratch Python golden (verify/golden_int4_gemm.py),
//   (2) drives the DUT over Wishbone B4 (load SRAM, config, START, poll DONE),
//   (3) reads OUT SRAM back and compares each INT8 byte against the golden
//       expected byte, counting mismatches,
//   (4) dumps every readback byte to verify/vectors/out.txt so an independent
//       Python cross-check can reconstruct the tiled (M/N and K) GEMMs.
//
// Vector files (all in verify/vectors/, concatenated in pass order):
//   passes.txt : line1 = num_passes ; then "scale shift k" (decimal) per pass
//   wmem.txt   : num_passes*32 hex weight words
//   amem.txt   : num_passes*32 hex act    words
//   expected.txt: num_passes*256 hex INT8 bytes (o = m*16+n order)
// ---------------------------------------------------------------------------
`timescale 1ns/1ps
`default_nettype none

module tb_functional;
    localparam [31:0] REG_BASE = 32'h0000_0000;
    localparam [31:0] WGT_BASE = 32'h0001_0000;
    localparam [31:0] ACT_BASE = 32'h0002_0000;
    localparam [31:0] OUT_BASE = 32'h0003_0000;

    localparam [31:0] R_CTRL = 32'h00, R_STATUS = 32'h04, R_M = 32'h08,
                      R_K = 32'h0C, R_N = 32'h10, R_SCALE = 32'h14,
                      R_SHIFT = 32'h18, R_IRQEN = 32'h1C, R_IRQST = 32'h20;

    reg         clk = 1'b0, rst_n = 1'b0, wb_rst = 1'b1;
    reg         stb = 0, cyc = 0, we = 0;
    reg  [3:0]  sel = 4'hF;
    reg  [31:0] adr = 0, dat_i = 0;
    wire        ack;
    wire [31:0] dat_o;
    wire        irq, ready, done;

    always #10 clk = ~clk;   // 50 MHz (20 ns)

    edge_llm_matmul_accel dut (
        .clk(clk), .rst_n(rst_n), .wb_clk_i(clk), .wb_rst_i(wb_rst),
        .wbs_stb_i(stb), .wbs_cyc_i(cyc), .wbs_we_i(we), .wbs_sel_i(sel),
        .wbs_dat_i(dat_i), .wbs_adr_i(adr),
        .wbs_ack_o(ack), .wbs_dat_o(dat_o),
        .irq_o(irq), .status_ready_o(ready), .status_done_o(done)
    );

    // -- Wishbone tasks (B4 classic single-word; handshake per DUT ack model) --
    task wb_write(input [31:0] a, input [31:0] d);
    begin
        @(negedge clk); stb=1; cyc=1; we=1; sel=4'hF; adr=a; dat_i=d;
        @(posedge clk);
        while (!ack) @(posedge clk);
        @(negedge clk); stb=0; cyc=0; we=0;
    end
    endtask

    task wb_read(input [31:0] a, output [31:0] d);
    begin
        @(negedge clk); stb=1; cyc=1; we=0; sel=4'hF; adr=a;
        @(posedge clk);
        while (!ack) @(posedge clk);
        d = dat_o;
        @(negedge clk); stb=0; cyc=0;
    end
    endtask

    // -- file handles + scratch ---------------------------------------------
    integer fp, fw, fa, fe, fo;
    integer num_passes, pass, i, code;
    integer scale_v, shift_v, k_v;
    reg [31:0] word;
    reg [31:0] rd;
    integer exp_byte, got_byte, o, wordidx, bytepos;
    integer mism_pass, mism_total, comps_total;
    integer done_polls, pp;

    initial begin
        // ---- reset ---------------------------------------------------------
        rst_n = 0; wb_rst = 1;
        repeat (4) @(posedge clk);
        @(negedge clk); rst_n = 1; wb_rst = 0;
        repeat (2) @(posedge clk);
        if (ready !== 1'b1)
            $display("WARN: status_ready not high after reset");

        // ---- open vector files --------------------------------------------
        fp = $fopen("verify/vectors/passes.txt", "r");
        fw = $fopen("verify/vectors/wmem.txt",   "r");
        fa = $fopen("verify/vectors/amem.txt",   "r");
        fe = $fopen("verify/vectors/expected.txt","r");
        fo = $fopen("verify/vectors/out.txt",    "w");
        if (fp == 0 || fw == 0 || fa == 0 || fe == 0 || fo == 0) begin
            $display("FAIL: could not open vector files (fp=%0d fw=%0d fa=%0d fe=%0d fo=%0d)",
                     fp, fw, fa, fe, fo);
            $finish;
        end

        code = $fscanf(fp, "%d\n", num_passes);
        $display("INFO: running %0d passes", num_passes);

        mism_total  = 0;
        comps_total = 0;

        for (pass = 0; pass < num_passes; pass = pass + 1) begin
            code = $fscanf(fp, "%d %d %d\n", scale_v, shift_v, k_v);

            // ---- load weight tile (32 words) ------------------------------
            for (i = 0; i < 32; i = i + 1) begin
                code = $fscanf(fw, "%h\n", word);
                wb_write(WGT_BASE + i*4, word);
            end
            // ---- load activation tile (32 words) --------------------------
            for (i = 0; i < 32; i = i + 1) begin
                code = $fscanf(fa, "%h\n", word);
                wb_write(ACT_BASE + i*4, word);
            end

            // ---- config ---------------------------------------------------
            wb_write(R_M,     32'd16);
            wb_write(R_K,     k_v);
            wb_write(R_N,     32'd16);
            wb_write(R_SCALE, scale_v);
            wb_write(R_SHIFT, shift_v);
            wb_write(R_IRQEN, 32'd1);

            // ---- START + poll STATUS.DONE ---------------------------------
            wb_write(R_CTRL, 32'd1);
            rd = 0;
            done_polls = 0;
            for (pp = 0; pp < 5000 && rd[1] == 1'b0; pp = pp + 1) begin
                wb_read(R_STATUS, rd);
                done_polls = done_polls + 1;
            end
            if (rd[1] !== 1'b1) begin
                $display("FAIL: pass %0d DONE never asserted (STATUS=0x%08x)", pass, rd);
                $fclose(fo);
                $finish;
            end

            // ---- read back OUT tile + compare vs golden expected ----------
            mism_pass = 0;
            for (o = 0; o < 256; o = o + 1) begin
                wordidx = o / 4;
                bytepos = o % 4;
                if (bytepos == 0)
                    wb_read(OUT_BASE + wordidx*4, rd);
                got_byte = $signed(rd[bytepos*8 +: 8]);
                code = $fscanf(fe, "%h\n", exp_byte);   // unsigned 0..255
                if (exp_byte > 127) exp_byte = exp_byte - 256;  // to signed
                // dump readback (as unsigned byte hex) for python cross-check
                $fwrite(fo, "%02x\n", got_byte & 8'hFF);
                comps_total = comps_total + 1;
                if (got_byte !== exp_byte) begin
                    mism_pass = mism_pass + 1;
                    mism_total = mism_total + 1;
                    if (mism_pass <= 6)
                        $display("  MISMATCH pass %0d o=%0d (C[%0d][%0d]): got=%0d exp=%0d",
                                 pass, o, o/16, o%16, got_byte, exp_byte);
                end
            end
            $display("INFO: pass %0d  K=%0d scale=%0d shift=%0d  polls=%0d  mismatches=%0d/256  %s",
                     pass, k_v, scale_v, shift_v, done_polls, mism_pass,
                     (mism_pass == 0) ? "PASS" : "FAIL");
        end

        $fclose(fo);
        $display("");
        $display("tests=%0d comparisons=%0d mismatches=%0d -> %s",
                 num_passes, comps_total, mism_total,
                 (mism_total == 0) ? "PASS" : "FAIL");
        $finish;
    end

    // watchdog
    initial begin
        #20_000_000;
        $display("FAIL: global timeout");
        $finish;
    end
endmodule

`default_nettype wire
